import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  buildDownloadPlan,
  createSink,
  loadMasterPlaylist,
  runDownload,
  sanitizeFileName,
  supportsFileSystemAccess,
} from '@/lib/download';
import type { DownloadPlan, DownloadProgress, MasterPlaylist, Variant } from '@/lib/download';

export interface DownloaderState {
  open: boolean;
  master: MasterPlaylist | null;
  plan: DownloadPlan | null;
  variantIndex: number;
  loadingManifest: boolean;
  loadingPlan: boolean;
  running: boolean;
  error: string;
  notice: string;
  progress: DownloadProgress;
}

function getIdleProgress(): DownloadProgress {
  return {
    phase: 'idle',
    message: '',
    segmentsDone: 0,
    segmentsTotal: 0,
    bytesWritten: 0,
    bytesDownloaded: 0,
    bytesPerSecond: 0,
    etaSeconds: 0,
    percent: 0,
  };
}

function describeError(error: unknown): string {
  if (error instanceof DOMException && error.name === 'AbortError') return 'A mentés megszakítva.';
  if (error instanceof TypeError) {
    return 'A tartalomkiszolgáló nem engedélyezi a közvetlen letöltést (CORS), vagy a hálózat megszakadt.';
  }
  if (error instanceof Error) return error.message;
  return 'Ismeretlen hiba a mentés közben.';
}

export function useDownloader(sourceUrl: string, titleHint: string) {
  const [state, setState] = useState<DownloaderState>(() => ({
    open: false,
    master: null,
    plan: null,
    variantIndex: 0,
    loadingManifest: false,
    loadingPlan: false,
    running: false,
    error: '',
    notice: '',
    progress: getIdleProgress(),
  }));

  const abortRef = useRef<AbortController | null>(null);
  const manifestAbortRef = useRef<AbortController | null>(null);
  const planAbortRef = useRef<AbortController | null>(null);

  useEffect(() => {
    abortRef.current?.abort();
    manifestAbortRef.current?.abort();
    planAbortRef.current?.abort();
    setState((current) => ({
      ...current,
      master: null,
      plan: null,
      variantIndex: 0,
      loadingManifest: false,
      loadingPlan: false,
      error: '',
      notice: '',
      progress: getIdleProgress(),
    }));
  }, [sourceUrl]);

  useEffect(() => {
    return () => {
      abortRef.current?.abort();
      manifestAbortRef.current?.abort();
      planAbortRef.current?.abort();
    };
  }, []);

  const selectedVariant = useMemo(() => {
    const master = state.master;
    if (!master) return null;
    const idx = state.variantIndex;
    if (idx >= 0 && idx < master.variants.length) return master.variants[idx];
    return null;
  }, [state.master, state.variantIndex]);

  const audioUri = useMemo(() => {
    if (!state.master || !selectedVariant) return null;
    const groupId = selectedVariant.audioGroup;
    if (!groupId) return null;
    const group = state.master.audio.filter((item) => item.groupId === groupId && !!item.uri);
    if (group.length === 0) return null;
    const preferred = group.find((item) => item.isDefault) ?? group[0];
    return preferred.uri ?? null;
  }, [state.master, selectedVariant]);

  const loadPlan = useCallback(
    async (variant: Variant, audio: string | null) => {
      planAbortRef.current?.abort();
      const controller = new AbortController();
      planAbortRef.current = controller;
      setState((current) => ({
        ...current,
        loadingPlan: true,
        error: '',
        plan: null,
      }));
      try {
        const plan = await buildDownloadPlan(variant, audio, controller.signal);
        if (controller.signal.aborted) return;
        const drm = plan.video.drmProtected || (plan.audio?.drmProtected ?? false);
        setState((current) => ({
          ...current,
          plan,
          loadingPlan: false,
          error: drm ? 'A kiválasztott sáv DRM-mel titkosított, a fájl mentése nem végezhető el.' : '',
          notice: plan.video.isLive ? 'Élő adás: a mentés a jelenleg elérhető ablakot rögzíti.' : '',
        }));
      } catch (error) {
        if (controller.signal.aborted) {
          setState((current) => ({ ...current, loadingPlan: false }));
          return;
        }
        setState((current) => ({
          ...current,
          loadingPlan: false,
          error: describeError(error),
        }));
      }
    },
    []
  );

  const openPanel = useCallback(async () => {
    setState((current) => ({ ...current, open: true, error: '' }));
    if (state.master) {
      return;
    }
    manifestAbortRef.current?.abort();
    const controller = new AbortController();
    manifestAbortRef.current = controller;
    setState((current) => ({
      ...current,
      loadingManifest: true,
      error: '',
    }));
    try {
      const master = await loadMasterPlaylist(sourceUrl, controller.signal);
      if (controller.signal.aborted) return;
      setState((current) => ({
        ...current,
        master,
        loadingManifest: false,
        variantIndex: 0,
        loadingPlan: false,
        plan: null,
        progress: getIdleProgress(),
      }));
      const primaryVariant = master.variants[0] ?? null;
      if (!primaryVariant) {
        setState((current) => ({
          ...current,
          loadingManifest: false,
          error: 'A manifestben nincs menthető sáv.',
        }));
        return;
      }
      const audio = (() => {
        if (!primaryVariant.audioGroup) return null;
        const group = master.audio.filter((item) => item.groupId === primaryVariant.audioGroup && !!item.uri);
        if (group.length === 0) return null;
        const pref = group.find((item) => item.isDefault) ?? group[0];
        return pref.uri ?? null;
      })();
      await loadPlan(primaryVariant, audio);
    } catch (error) {
      if (controller.signal.aborted) {
        setState((current) => ({ ...current, loadingManifest: false }));
        return;
      }
      setState((current) => ({
        ...current,
        loadingManifest: false,
        error: describeError(error),
      }));
    }
  }, [sourceUrl, state.master, loadPlan]);

  const closePanel = useCallback(() => {
    abortRef.current?.abort();
    manifestAbortRef.current?.abort();
    planAbortRef.current?.abort();
    setState((current) => ({
      ...current,
      open: false,
      error: '',
      notice: '',
      progress: getIdleProgress(),
    }));
  }, []);

  const selectVariant = useCallback(
    (index: number) => {
      if (index < 0) {
        setState((current) => ({
          ...current,
          error: 'Érvénytelen sáv index.',
        }));
        return;
      }
      const master = state.master;
      if (!master) {
        setState((current) => ({
          ...current,
          error: 'Nincs betöltve manifest.',
        }));
        return;
      }
      if (index >= master.variants.length) {
        setState((current) => ({
          ...current,
          error: 'Sáv index kívül esik a tartományon.',
        }));
        return;
      }
      const variant = master.variants[index];
      const audio = (() => {
        if (!variant.audioGroup) return null;
        const group = master.audio.filter((item) => item.groupId === variant.audioGroup && !!item.uri);
        if (group.length === 0) return null;
        const pref = group.find((item) => item.isDefault) ?? group[0];
        return pref.uri ?? null;
      })();
      setState((current) => ({
        ...current,
        variantIndex: index,
        error: '',
        notice: '',
        loadingPlan: true,
        plan: null,
        progress: getIdleProgress(),
      }));
      void loadPlan(variant, audio);
    },
    [state.master, loadPlan]
  );

  const cancel = useCallback(() => {
    abortRef.current?.abort();
    setState((current) => ({
      ...current,
      running: false,
      progress: {
        ...current.progress,
        phase: 'cancelled',
        message: 'Megszakítva.',
      },
    }));
  }, []);

  const start = useCallback(async () => {
    const plan = state.plan;
    const variant = selectedVariant;
    if (!plan || !variant) return;
    if (plan.video.drmProtected || (plan.audio?.drmProtected ?? false)) return;
    if (state.running) return;
    const baseName = sanitizeFileName(`${titleHint?.trim() || 'stream'}-${variant.height && variant.height > 0 ? `${variant.height}p` : 'audio'}`);
    const fileName = `${baseName}${plan.extension.startsWith('.') ? plan.extension : `.${plan.extension}`}`;
    let sink: Awaited<ReturnType<typeof createSink>> | null = null;
    try {
      sink = await createSink(fileName, plan.mimeType, plan.extension);
    } catch (error) {
      setState((current) => ({
        ...current,
        error: describeError(error),
        running: false,
      }));
      return;
    }
    const controller = new AbortController();
    abortRef.current = controller;
    setState((current) => ({
      ...current,
      running: true,
      error: '',
      notice:
        sink.kind === 'memory'
          ? 'A böngésző nem támogatja a közvetlen lemezre írást, a fájl a memóriában készül el.'
          : current.notice,
      progress: { ...getIdleProgress(), phase: 'downloading', message: 'Indítás…', segmentsTotal: plan.segmentCount },
    }));
    try {
      await runDownload({
        plan,
        sink,
        fileBaseName: baseName,
        signal: controller.signal,
        onProgress: (progress) => setState((current) => ({ ...current, progress })),
      });
      setState((current) => ({
        ...current,
        running: false,
        progress: { ...current.progress, phase: 'done', message: 'Kész.' },
      }));
    } catch (error) {
      if (sink) {
        try {
          await sink.abort();
        } catch {}
      }
      const aborted = controller.signal.aborted;
      setState((current) => ({
        ...current,
        running: false,
        error: aborted ? '' : describeError(error),
        progress: {
          ...current.progress,
          phase: aborted ? 'cancelled' : 'error',
          message: aborted ? 'Megszakítva.' : describeError(error),
        },
      }));
    } finally {
      abortRef.current = null;
    }
  }, [state.plan, state.running, selectedVariant, titleHint]);

  const directDiskWrite = useMemo(() => supportsFileSystemAccess(), []);

  const returned = useMemo(
    () => ({
      ...state,
      selectedVariant,
      audioUri,
      directDiskWrite,
      openPanel,
      closePanel,
      selectVariant,
      start,
      cancel,
    }),
    [
      state,
      selectedVariant,
      audioUri,
      directDiskWrite,
      openPanel,
      closePanel,
      selectVariant,
      start,
      cancel,
    ]
  );

  return returned;
}
```

